CREATE TABLE IF NOT EXISTS public."Players"
(
    player_id serial NOT NULL,
    surname character varying(50) NOT NULL,
    name character varying(50) NOT NULL,
    patronymic character varying(50),
    country_id integer NOT NULL,
    birth_date date NOT NULL,
    PRIMARY KEY (player_id),
	CONSTRAINT check_birth_date CHECK (birth_date >= '1900-01-01'::date AND birth_date <= CURRENT_DATE)
);

CREATE TABLE IF NOT EXISTS public."Country"
(
    id_country serial,
    short_name character varying(3) NOT NULL,
    long_name character varying(100) NOT NULL,
    region character varying(50) NOT NULL,
    PRIMARY KEY (id_country),
    CONSTRAINT sh_name UNIQUE (short_name),
    CONSTRAINT l_name UNIQUE (long_name),
	CONSTRAINT check_region CHECK (region IN (
        'Европа', 
        'Азия', 
        'Африка', 
        'Северная Америка', 
        'Южная Америка', 
        'Латинская Америка',
        'Австралия и Океания'
    ))
);

CREATE TABLE IF NOT EXISTS public."Club"
(
    club_id serial,
    short_name character varying(50) NOT NULL,
    long_name character varying(100) NOT NULL,
    PRIMARY KEY (club_id),
    CONSTRAINT club_l_name UNIQUE (long_name)
);

CREATE TABLE IF NOT EXISTS public."Team"
(
    team_id serial,
    team_name character varying(50) NOT NULL,
    country_id integer,
    club_id integer,
    PRIMARY KEY (team_id),
    CONSTRAINT team_name_team UNIQUE (team_name),
	CONSTRAINT check_team_affiliation CHECK (
        (country_id IS NOT NULL AND club_id IS NULL) OR 
        (country_id IS NULL AND club_id IS NOT NULL)
    )
);

CREATE TABLE IF NOT EXISTS public."Team_player"
(
    id serial,
