    CONSTRAINT check_position CHECK ("position" IN (
        'Forward', 'Midfielder', 'Defender', 'Goalkeeper',
        'Нападающий', 'Полузащитник', 'Защитник', 'Вратарь'
    ))
);

CREATE TABLE IF NOT EXISTS public."Bracket"
(
    id serial,
    round_name character varying(50) NOT NULL,
    parent_bracket_id integer,
    PRIMARY KEY (id),
    UNIQUE (round_name),
	CONSTRAINT check_round_name CHECK (round_name IN (
		'Группа A', 'Группа B', 'Группа C', 'Группа D',
		'1/8 финала', '1/4 финала', 'Полуфинал', 'Финал', 'Матч за 3 место'
	))
);

CREATE TABLE IF NOT EXISTS public."Match"
(
    id_match serial,
    bracket_id integer NOT NULL,
    location character varying(50) NOT NULL,
    match_date date NOT NULL,
    match_time time without time zone NOT NULL,
    PRIMARY KEY (id_match),
	UNIQUE (location, match_date, match_time),
	CONSTRAINT check_future_match CHECK (match_date >= CURRENT_DATE)
);

CREATE TABLE IF NOT EXISTS public."Game_team"
