	CONSTRAINT check_violation_minute CHECK ("minute" >= 0 AND "minute" <= 120),
    CONSTRAINT check_card_type CHECK (card_type IN ('Yellow', 'Red', 'Green'))
	
);

CREATE TABLE IF NOT EXISTS public."Results"
(
    result_id serial NOT NULL,
    game_team_id integer NOT NULL,
    score integer NOT NULL DEFAULT 0,
    penalties integer,
