    PRIMARY KEY (result_id),
    UNIQUE (game_team_id),
	CONSTRAINT check_result_score CHECK (score >= 0),
	CONSTRAINT check_penalties CHECK (penalties >= 0),
    CONSTRAINT check_points CHECK (points >= 0)
);


