--Список всех игроков с названием их стран
SELECT p.surname, p.name, c.long_name  FROM "Players" p
JOIN "Country" c ON p.country_id = c.id_country;

--Cостав на конкретный матч
SELECT t.team_name, tp."number", tp."position", 
       p.surname, p.name
FROM "Team_player" tp
JOIN "Game_team" gt ON tp.game_team_id = gt.game_team_id
JOIN "Team" t ON gt.team_id = t.team_id
JOIN "Players" p ON tp.player_id = p.player_id
WHERE gt.match_id = 1
ORDER BY t.team_name, tp."position";

--Количество голов, забитых в каждом тайме
SELECT 
    CASE 
        WHEN "minute" <= 45 THEN '1-й тайм'
        WHEN "minute" <= 90 THEN '2-й тайм'
        ELSE 'Дополнительное время'
    END AS match_period,
    COUNT(*) AS goals_count
FROM "Goal"
GROUP BY match_period
ORDER BY MIN("minute");

--Игроки, которые ни разу не получали карточки
SELECT p.surname, p.name  FROM "Players" p
WHERE p.player_id NOT IN 
				(SELECT DISTINCT tp.player_id FROM "Team_player" tp 
				 JOIN "Violation" v ON tp.id =v.team_player_id
                );
				
--Матчи, в которых было забито больше всего голов.
SELECT m.id_match, m.location, m.match_date, 
       SUM(r.score) AS total_match_goals
FROM "Match" m
JOIN "Game_team" gt ON m.id_match = gt.match_id
JOIN "Results" r ON gt.game_team_id = r.game_team_id
GROUP BY m.id_match, m.location, m.match_date
ORDER BY total_match_goals DESC
LIMIT 3;

--суммарное количество голов, забитых каждым игроком.
SELECT p.surname, COUNT(g.goal_id) AS count_goals
FROM "Players" p
JOIN "Team_player" tp ON p.player_id = tp.player_id
LEFT JOIN "Goal" g ON tp.id = g.team_player_id
GROUP BY p.player_id, p.surname
ORDER BY count_goals DESC;

--Cреднее число нарушений в матче (среднее число карточек по всем матчам).
SELECT ROUND(AVG(violation_count), 2) AS average_number_of_cards_per_match
FROM (
    SELECT m.id_match, COUNT(v.violation_id) AS violation_count
    FROM "Match" m
    JOIN "Game_team" gt ON m.id_match = gt.match_id
    JOIN "Team_player" tp ON gt.game_team_id = tp.game_team_id
    LEFT JOIN "Violation" v ON tp.id = v.team_player_id
    GROUP BY m.id_match
) AS match_violations;

--Команды, которые выиграли матч, но не забили ни одного гола
SELECT t.team_name, r.score
FROM "Team" t
JOIN "Game_team" gt ON t.team_id = gt.team_id
JOIN "Results" r ON gt.game_team_id = r.game_team_id
WHERE r.points = 3 
  AND r.score = 0;

--Стадионы, которые приняли более одного матча
SELECT location, COUNT(id_match) AS matches_hosted
FROM "Match"
GROUP BY location
HAVING COUNT(id_match) > 1;

--Возраст игроков на день первого матча их команды.
SELECT pl.surname, pl.name, t.team_name, 
       m.match_date,
       EXTRACT(YEAR FROM AGE(m.match_date, pl.birth_date)) AS age_at_match
FROM "Players" pl
JOIN "Team_player" tp ON pl.player_id = tp.player_id
JOIN "Game_team" gt ON tp.game_team_id = gt.game_team_id
JOIN "Match" m ON gt.match_id = m.id_match
JOIN "Team" t ON gt.team_id = t.team_id
WHERE m.match_date = (
    SELECT MIN(m2.match_date) 
    FROM "Match" m2 
    JOIN "Game_team" gt2 ON m2.id_match = gt2.match_id 
    WHERE gt2.team_id = t.team_id
)
ORDER BY age_at_match DESC;

-- Рейтинг игроков по количеству голов внутри их позиции
SELECT tp."position", pl.surname, pl.name, COUNT(g.goal_id) AS goals,
       RANK() OVER(PARTITION BY tp."position" ORDER BY COUNT(g.goal_id) DESC) AS pos_rank
FROM "Team_player" tp
JOIN "Players" pl ON tp.player_id = pl.player_id
LEFT JOIN "Goal" g ON tp.id = g.team_player_id
GROUP BY tp."position", pl.player_id, pl.surname, pl.name
ORDER BY tp."position", pos_rank;

--Игроки, которые играли на разных позициях в разных матчах
SELECT pl.surname, pl.name, COUNT(DISTINCT tp."position") AS positions_played
FROM "Players" pl
JOIN "Team_player" tp ON pl.player_id = tp.player_id
GROUP BY pl.player_id, pl.surname, pl.name
HAVING COUNT(DISTINCT tp."position") > 1;

--Команды, которые ни разу не играли дома
SELECT t.team_name
FROM "Team" t
WHERE NOT EXISTS (
    SELECT 1 FROM "Game_team" gt 
    WHERE gt.team_id = t.team_id AND gt.is_home = TRUE
)
AND EXISTS (
    SELECT 1 FROM "Game_team" gt 
    WHERE gt.team_id = t.team_id
);
  
--Cамый результативный по голам и самый результативный по нарушениям матчи.
WITH match_stats AS (
    SELECT m.id_match, m.location, m.match_date,
        COUNT(DISTINCT g.goal_id) AS goal_count,
        COUNT(DISTINCT v.violation_id) AS violation_count
    FROM "Match" m
    JOIN "Game_team" gt ON m.id_match = gt.match_id
    JOIN "Team_player" tp ON gt.game_team_id = tp.game_team_id
    LEFT JOIN "Goal" g ON tp.id = g.team_player_id
    LEFT JOIN "Violation" v ON tp.id = v.team_player_id
    GROUP BY m.id_match, m.location, m.match_date
)
SELECT 
    'Самый результативный по голам' AS statistic_type,
    id_match,
    location,
    match_date,
    goal_count AS value
FROM match_stats
WHERE goal_count = (SELECT MAX(goal_count) FROM match_stats)

UNION ALL

SELECT 
    'Самый результативный по нарушениям' AS statistic_type,
    id_match,
    location,
    match_date,
    violation_count AS value
FROM match_stats
WHERE violation_count = (SELECT MAX(violation_count) FROM match_stats);

--Замена названия всех клубов, дописав спереди фразу «Футбольный клуб»
UPDATE public."Club"
SET long_name = 'Футбольный клуб' || long_name;
	
